CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT '', accent TEXT NOT NULL DEFAULT 'indigo', temperature REAL NOT NULL DEFAULT 0.7, top_p REAL NOT NULL DEFAULT 0.9, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_state (profile_id TEXT PRIMARY KEY REFERENCES profiles(id) ON DELETE CASCADE, active INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS proxies (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', type TEXT NOT NULL, host TEXT NOT NULL, port INTEGER NOT NULL, username TEXT NOT NULL DEFAULT '', password TEXT NOT NULL DEFAULT '', insecure_skip_verify INTEGER NOT NULL DEFAULT 0, profile_id TEXT NOT NULL DEFAULT 'default', UNIQUE(profile_id, name));
CREATE INDEX IF NOT EXISTS idx_proxies_profile_id ON proxies(profile_id);
CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', system_prompt TEXT NOT NULL DEFAULT '', icon_key TEXT NOT NULL DEFAULT 'bot', accent TEXT NOT NULL DEFAULT 'indigo', compaction_level TEXT NOT NULL DEFAULT 'balanced');
CREATE TABLE IF NOT EXISTS agents_links (agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, link_type TEXT NOT NULL CHECK(link_type IN ('mainModel','memModel','toolModel','compactionModel','skillGroupId','mcpId')), other_id TEXT NOT NULL, PRIMARY KEY(agent_id, profile_id, link_type, other_id));
CREATE INDEX IF NOT EXISTS agents_links_lookup ON agents_links(profile_id, agent_id, link_type);
CREATE TABLE IF NOT EXISTS presets (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, title TEXT NOT NULL, text TEXT NOT NULL, agent_id TEXT);
CREATE TABLE IF NOT EXISTS profile_providers (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL, base_url TEXT NOT NULL, api_key TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, proxy_id TEXT NOT NULL DEFAULT '', proxy_type TEXT NOT NULL DEFAULT '', proxy_host TEXT NOT NULL DEFAULT '', proxy_port INTEGER NOT NULL DEFAULT 0, proxy_username TEXT NOT NULL DEFAULT '', proxy_password TEXT NOT NULL DEFAULT '', rpm INTEGER NOT NULL DEFAULT 0 CHECK (rpm >= 0), UNIQUE(profile_id, name));
CREATE TABLE IF NOT EXISTS profile_providers_model (model_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES profile_providers(id) ON DELETE CASCADE, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, model_name TEXT NOT NULL, UNIQUE(profile_id, provider_id, model_name));
CREATE INDEX IF NOT EXISTS profile_providers_model_lookup ON profile_providers_model(profile_id, provider_id);
CREATE TABLE IF NOT EXISTS profile_mcp_servers (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, name TEXT NOT NULL, transport TEXT NOT NULL, command TEXT NOT NULL DEFAULT '', url TEXT NOT NULL DEFAULT '', headers TEXT NOT NULL DEFAULT '[]', prefix TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, tools TEXT NOT NULL DEFAULT '[]', instructions TEXT NOT NULL DEFAULT '', UNIQUE(profile_id, name));
CREATE TABLE IF NOT EXISTS profile_builtin_mcp_settings (profile_id TEXT NOT NULL, builtin_key TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, tools TEXT NOT NULL DEFAULT '[]', PRIMARY KEY(profile_id, builtin_key));
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, folder_path TEXT NOT NULL, opened_at TEXT NOT NULL, profile_id TEXT NOT NULL DEFAULT 'default', UNIQUE(profile_id, folder_path));
CREATE INDEX IF NOT EXISTS idx_workspaces_profile_id ON workspaces(profile_id);
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, workspace_id TEXT NOT NULL, agent_id TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, updated_at TEXT NOT NULL, active_model TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS conversations_profile_workspace ON conversations(profile_id, workspace_id, updated_at DESC);
CREATE TABLE IF NOT EXISTS local_llm_settings (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, runtime TEXT NOT NULL
    CHECK(runtime IN ('ollama','llama')), enabled INTEGER NOT NULL DEFAULT 0, binary_path TEXT NOT NULL DEFAULT '', launch_args TEXT NOT NULL DEFAULT '[]', models_path TEXT NOT NULL DEFAULT '', env TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(profile_id, runtime));
